import { useCallback, useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import {
  FiAlertCircle,
  FiCalendar,
  FiCheckCircle,
  FiClock,
  FiRefreshCw,
  FiTrendingUp,
  FiUserCheck,
  FiUsers,
  FiXCircle,
} from "react-icons/fi";
import { PATHS } from "../../app/router/paths";
import {
  getTrainerCourseAttendanceSummary,
  getTrainerCourseStudentAttendance,
  getTrainerSessionAttendance,
} from "../api/trainerAttendanceApi";

const emptyCourseReport = {
  courseId: "",
  courseTitle: "Course attendance",
  trainerId: "",
  totalStudents: 0,
  totalSessions: 0,
  completedSessions: 0,
  presentCount: 0,
  lateCount: 0,
  absentCount: 0,
  attendedCount: 0,
  averageAttendancePercentage: 0,
  students: [],
  sessions: [],
};

const emptySessionReport = {
  sessionId: "",
  occurrenceId: "",
  sessionTitle: "Session attendance",
  occurrenceDate: "",
  startsAt: "",
  endsAt: "",
  totalStudents: 0,
  presentCount: 0,
  lateCount: 0,
  absentCount: 0,
  attendedCount: 0,
  attendancePercentage: 0,
  students: [],
};

function formatPercent(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "0%";
  return `${number.toFixed(number % 1 === 0 ? 0 : 1)}%`;
}

function formatDate(value) {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function formatTime(value) {
  if (!value) return "-";
  const date = new Date(value);
  if (!Number.isNaN(date.getTime())) {
    return date.toLocaleTimeString("en-IN", {
      hour: "numeric",
      minute: "2-digit",
    });
  }
  if (/^\d{2}:\d{2}/.test(String(value))) return String(value).slice(0, 5);
  return String(value);
}

function statusClass(status) {
  const value = String(status || "").toLowerCase();
  if (value === "present") return "bg-emerald-50 text-emerald-700";
  if (value === "late") return "bg-amber-50 text-amber-700";
  return "bg-red-50 text-red-700";
}

function StatCard({ label, value, icon: Icon, tone = "slate" }) {
  const toneClass =
    tone === "green"
      ? "bg-emerald-50 text-emerald-700"
      : tone === "amber"
        ? "bg-amber-50 text-amber-700"
        : tone === "red"
          ? "bg-red-50 text-red-700"
          : "bg-slate-50 text-slate-700";

  return (
    <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
      <div className={`inline-flex h-9 w-9 items-center justify-center rounded-lg ${toneClass}`}>
        <Icon />
      </div>
      <div className="mt-3 text-xl font-extrabold text-slate-950">{value}</div>
      <div className="mt-1 text-xs font-bold uppercase tracking-wider text-slate-500">{label}</div>
    </div>
  );
}

function ProgressBar({ value }) {
  const width = Math.max(0, Math.min(100, Number(value) || 0));
  return (
    <div className="h-2 overflow-hidden rounded-full bg-slate-100">
      <div className="h-full rounded-full bg-[#006b58]" style={{ width: `${width}%` }} />
    </div>
  );
}

function EmptyState({ title, message }) {
  return (
    <div className="rounded-xl border border-dashed border-slate-200 bg-slate-50 p-8 text-center">
      <div className="text-base font-extrabold text-slate-900">{title}</div>
      <p className="mt-1 text-sm text-slate-500">{message}</p>
    </div>
  );
}

export default function TrainerAttendancePage({ view = "course" }) {
  const { courseId = "", sessionId = "" } = useParams();
  const isSessionView = view === "session";
  const [courseReport, setCourseReport] = useState(emptyCourseReport);
  const [sessionReport, setSessionReport] = useState(emptySessionReport);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadReport = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      if (isSessionView) {
        const next = await getTrainerSessionAttendance(sessionId);
        setSessionReport({ ...emptySessionReport, ...next });
      } else {
        const [summary, studentReport] = await Promise.all([
          getTrainerCourseAttendanceSummary(courseId),
          getTrainerCourseStudentAttendance(courseId),
        ]);
        setCourseReport({
          ...emptyCourseReport,
          ...summary,
          students: studentReport.students?.length ? studentReport.students : summary.students,
        });
      }
    } catch (err) {
      setError(err?.message || "Unable to load attendance report.");
    } finally {
      setLoading(false);
    }
  }, [courseId, isSessionView, sessionId]);

  useEffect(() => {
    loadReport();
  }, [loadReport]);

  const title = isSessionView ? sessionReport.sessionTitle : courseReport.courseTitle;
  const summaryCards = useMemo(() => {
    if (isSessionView) {
      return [
        ["Total Students", sessionReport.totalStudents, FiUsers],
        ["Present", sessionReport.presentCount, FiCheckCircle, "green"],
        ["Late", sessionReport.lateCount, FiClock, "amber"],
        ["Absent", sessionReport.absentCount, FiXCircle, "red"],
        ["Attended", sessionReport.attendedCount, FiUserCheck, "green"],
        ["Attendance", formatPercent(sessionReport.attendancePercentage), FiTrendingUp, "green"],
      ];
    }
    return [
      ["Total Students", courseReport.totalStudents, FiUsers],
      ["Total Sessions", courseReport.totalSessions, FiCalendar],
      ["Completed", courseReport.completedSessions, FiCheckCircle],
      ["Present", courseReport.presentCount, FiCheckCircle, "green"],
      ["Late", courseReport.lateCount, FiClock, "amber"],
      ["Absent", courseReport.absentCount, FiXCircle, "red"],
      ["Attended", courseReport.attendedCount, FiUserCheck, "green"],
      ["Average", formatPercent(courseReport.averageAttendancePercentage), FiTrendingUp, "green"],
    ];
  }, [courseReport, isSessionView, sessionReport]);

  return (
    <main className="min-h-dvh bg-[#f4f7f6] text-slate-950">
      <section className="border-b border-slate-200 bg-white">
        <div className="mx-auto max-w-7xl px-4 py-7 sm:px-6">
          <Link
            to={PATHS.TRAINER_DASHBOARD}
            className="text-xs font-extrabold uppercase tracking-widest text-[#006b58]"
          >
            Trainer dashboard
          </Link>
          <div className="mt-3 flex flex-col justify-between gap-4 lg:flex-row lg:items-end">
            <div>
              <h1 className="text-2xl font-black tracking-tight text-slate-950 sm:text-3xl">
                {title}
              </h1>
              <p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500">
                {isSessionView
                  ? "View finalized attendance for this session. Trainers cannot edit attendance."
                  : "Review course attendance across completed sessions and students. Trainers see only their own courses."}
              </p>
            </div>
            <button
              type="button"
              onClick={loadReport}
              className="inline-flex h-11 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-5 text-sm font-extrabold text-slate-700 transition-colors hover:border-[#006b58]"
            >
              <FiRefreshCw className={loading ? "animate-spin" : ""} />
              Refresh
            </button>
          </div>
        </div>
      </section>

      <section className="mx-auto max-w-7xl px-4 py-6 sm:px-6">
        {error ? (
          <div className="mb-5 flex items-start gap-2 rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm font-semibold text-red-700">
            <FiAlertCircle className="mt-0.5 flex-shrink-0" />
            <span>{error}</span>
          </div>
        ) : null}

        {loading ? (
          <div className="rounded-2xl border border-slate-200 bg-white p-10 text-center shadow-sm">
            <span className="mx-auto block h-9 w-9 animate-spin rounded-full border-2 border-slate-200 border-t-[#00342b]" />
            <div className="mt-3 text-lg font-extrabold">Loading attendance report</div>
            <p className="mt-1 text-sm text-slate-500">Fetching finalized attendance data.</p>
          </div>
        ) : (
          <div className="space-y-6">
            {isSessionView ? (
              <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5">
                <div className="grid grid-cols-1 gap-3 text-sm sm:grid-cols-3">
                  <div>
                    <div className="text-xs font-bold uppercase tracking-wider text-slate-500">Occurrence date</div>
                    <div className="mt-1 font-extrabold">{formatDate(sessionReport.occurrenceDate)}</div>
                  </div>
                  <div>
                    <div className="text-xs font-bold uppercase tracking-wider text-slate-500">Start time</div>
                    <div className="mt-1 font-extrabold">{formatTime(sessionReport.startsAt)}</div>
                  </div>
                  <div>
                    <div className="text-xs font-bold uppercase tracking-wider text-slate-500">End time</div>
                    <div className="mt-1 font-extrabold">{formatTime(sessionReport.endsAt)}</div>
                  </div>
                </div>
              </div>
            ) : null}

            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {summaryCards.map(([label, value, Icon, tone]) => (
                <StatCard key={label} label={label} value={value} icon={Icon} tone={tone} />
              ))}
            </div>

            {!isSessionView ? (
              <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5">
                <h2 className="text-lg font-extrabold">Session-wise attendance table</h2>
                <p className="mt-1 text-sm text-slate-500">
                  Attendance finalizes after each session ends.
                </p>

                <div className="mt-5 overflow-x-auto">
                  {courseReport.sessions.length ? (
                    <table className="min-w-full text-left text-sm">
                      <thead>
                        <tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500">
                          <th className="px-3 py-3 font-extrabold">Session title</th>
                          <th className="px-3 py-3 font-extrabold">Occurrence date</th>
                          <th className="px-3 py-3 font-extrabold">Start time</th>
                          <th className="px-3 py-3 font-extrabold">End time</th>
                          <th className="px-3 py-3 font-extrabold">Present</th>
                          <th className="px-3 py-3 font-extrabold">Late</th>
                          <th className="px-3 py-3 font-extrabold">Absent</th>
                          <th className="px-3 py-3 font-extrabold">Total students</th>
                          <th className="px-3 py-3 font-extrabold">Attendance %</th>
                        </tr>
                      </thead>
                      <tbody>
                        {courseReport.sessions.map((session) => (
                          <tr key={session.occurrenceId || session.sessionId} className="border-b border-slate-100">
                            <td className="px-3 py-3">
                              <Link
                                to={`/trainer/sessions/${encodeURIComponent(session.sessionId)}/attendance`}
                                className="font-extrabold text-[#006b58] hover:underline"
                              >
                                {session.sessionTitle}
                              </Link>
                            </td>
                            <td className="px-3 py-3 font-semibold text-slate-600">{formatDate(session.occurrenceDate)}</td>
                            <td className="px-3 py-3">{formatTime(session.startsAt)}</td>
                            <td className="px-3 py-3">{formatTime(session.endsAt)}</td>
                            <td className="px-3 py-3 text-emerald-700">{session.presentCount}</td>
                            <td className="px-3 py-3 text-amber-700">{session.lateCount}</td>
                            <td className="px-3 py-3 text-red-700">{session.absentCount}</td>
                            <td className="px-3 py-3">{session.totalStudents}</td>
                            <td className="px-3 py-3">
                              <div className="min-w-32">
                                <div className="mb-1 font-extrabold">{formatPercent(session.attendancePercentage)}</div>
                                <ProgressBar value={session.attendancePercentage} />
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <EmptyState
                      title="No session attendance yet"
                      message="Completed sessions will appear here after attendance is finalized."
                    />
                  )}
                </div>
              </div>
            ) : null}

            <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5">
              <h2 className="text-lg font-extrabold">
                {isSessionView ? "Session student attendance" : "Student-wise attendance table"}
              </h2>
              <p className="mt-1 text-sm text-slate-500">
                {isSessionView
                  ? "Read-only per-student session attendance details."
                  : "Eligibility status is display-only for future certificate planning."}
              </p>

              <div className="mt-5 overflow-x-auto">
                {isSessionView ? (
                  sessionReport.students.length ? (
                    <table className="min-w-full text-left text-sm">
                      <thead>
                        <tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500">
                          <th className="px-3 py-3 font-extrabold">Student name</th>
                          <th className="px-3 py-3 font-extrabold">Email</th>
                          <th className="px-3 py-3 font-extrabold">Status</th>
                          <th className="px-3 py-3 font-extrabold">First joined</th>
                          <th className="px-3 py-3 font-extrabold">Last joined</th>
                          <th className="px-3 py-3 font-extrabold">Join count</th>
                        </tr>
                      </thead>
                      <tbody>
                        {sessionReport.students.map((student) => (
                          <tr key={student.studentId || student.email} className="border-b border-slate-100">
                            <td className="px-3 py-3 font-extrabold text-slate-900">{student.fullName}</td>
                            <td className="px-3 py-3 font-semibold text-slate-500">{student.email || "-"}</td>
                            <td className="px-3 py-3">
                              <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-extrabold capitalize ${statusClass(student.status)}`}>
                                {student.status}
                              </span>
                            </td>
                            <td className="px-3 py-3">{formatTime(student.firstJoinedAt)}</td>
                            <td className="px-3 py-3">{formatTime(student.lastJoinedAt)}</td>
                            <td className="px-3 py-3">{student.joinCount}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <EmptyState
                      title="No student records"
                      message="Student attendance records will appear after attendance finalizes."
                    />
                  )
                ) : courseReport.students.length ? (
                  <table className="min-w-full text-left text-sm">
                    <thead>
                      <tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500">
                        <th className="px-3 py-3 font-extrabold">Student name</th>
                        <th className="px-3 py-3 font-extrabold">Email</th>
                        <th className="px-3 py-3 font-extrabold">Present</th>
                        <th className="px-3 py-3 font-extrabold">Late</th>
                        <th className="px-3 py-3 font-extrabold">Absent</th>
                        <th className="px-3 py-3 font-extrabold">Attended sessions</th>
                        <th className="px-3 py-3 font-extrabold">Total sessions</th>
                        <th className="px-3 py-3 font-extrabold">Attendance %</th>
                        <th className="px-3 py-3 font-extrabold">Eligibility status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {courseReport.students.map((student) => (
                        <tr key={student.studentId || student.email} className="border-b border-slate-100">
                          <td className="px-3 py-3 font-extrabold text-slate-900">{student.fullName}</td>
                          <td className="px-3 py-3 font-semibold text-slate-500">{student.email || "-"}</td>
                          <td className="px-3 py-3 text-emerald-700">{student.presentCount}</td>
                          <td className="px-3 py-3 text-amber-700">{student.lateCount}</td>
                          <td className="px-3 py-3 text-red-700">{student.absentCount}</td>
                          <td className="px-3 py-3">{student.attendedCount}</td>
                          <td className="px-3 py-3">{student.totalSessions}</td>
                          <td className="px-3 py-3">
                            <div className="min-w-32">
                              <div className="mb-1 font-extrabold">{formatPercent(student.attendancePercentage)}</div>
                              <ProgressBar value={student.attendancePercentage} />
                            </div>
                          </td>
                          <td className="px-3 py-3">
                            <span className="inline-flex rounded-full bg-slate-50 px-2.5 py-1 text-xs font-extrabold text-slate-700">
                              {student.eligibilityStatus}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (
                  <EmptyState
                    title="No student attendance yet"
                    message="Student-wise attendance appears after students join completed sessions."
                  />
                )}
              </div>
            </div>
          </div>
        )}
      </section>
    </main>
  );
}
